items=[]
def add(q,summary,values,reasons,solution,concept,labels,knowledge,cites,ambiguity='',negative=False):
 r=by[q];a=int(initial[q]['independent_answer']);assert len(values)==len(reasons)==5
 choices={str(i):dict(value=v,verdict=('該当しない対象' if i==a else '対象範囲を検討') if negative else ('独立判断で適切' if i==a else '不適切'),reason=w) for i,(v,w) in enumerate(zip(values,reasons),1)}
 if q=='R03-REG-APT-07':
  choices['4']['verdict']='一般命題としての独立初回判断'
  choices['5']['verdict']='典型例としての公式判断'
 items.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=summary,summary=summary,
 conditions={'判断対象':'広義知的財産・産業財産権・引用・営業秘密を区別する。','原典照合':'15問の原典画像について問題幹、否定、表の列順、全5候補を確認。','法の時点':'出題時の制度を保持し、説明の取得基準日は2026-10-12とする。'},
 choices=choices,figures='組合せ表の全5行を画像確認。原典の長文は独自要約へ変換し、正誤と選択肢の対応を保持する。',
 ambiguity=ambiguity,evidence=[initial[q]['image']],core_concept=summary,required_knowledge=knowledge,solution=solution,answer_reason=solution,
 independent_answer=initial[q]['independent_answer'],independent_solution_note='全15原典画像を確認し公式参照前に初回解答を保存。'+initial[q]['reason']+'初回記録は照合後も変更しない。',
 learning_points='保護する対象、制度の範囲、成立要件、許諾なし利用の条件を分ける。典型例の名称から成立要件を省略せず、正誤表の行と対象数を対応させる。',
 theory_references=labels,discipline_id='apt_4',concept_id=concept,cross_concepts=[],
 classification_reason='原典の中心は知的財産制度・著作権・営業秘密の法的要件である。研究・情報倫理apt_1から、既存の知的財産共通理論を持つコンプライアンスapt_4へ主分類を修正する。創作の倫理一般と権利の成立・制限を区別する。',
 calculation='false',figure='false',law='true',
 evaluation=dict(knowledge_novelty='2',reasoning_steps='2',calculation_load='0',figure_reading='1' if '正誤' in knowledge else '0',difficulty='3' if ambiguity else '2',difficulty_reason='数学負荷はない。法的範囲、要件の論理、表の対応を理解する負荷を評価する。条件省略・当時版の未照合は不確実性として別に残す。'),
 citations=cites,foundationality='high',transferability='high'))

